for number in 098 099; do
 migration=("$WEB_ROOT"/database/migrations/"${number}"_*.sql)
 docker exec -i "$CONTAINER_NAME" psql -U postgres -v ON_ERROR_STOP=1 -q < "${migration[0]}"
 docker exec -i "$CONTAINER_NAME" psql -U postgres -v ON_ERROR_STOP=1 -q <<SQL
do \$\$ begin if (select schema_version from public.application_schema_state where contract_key='core')<>$((10#$number)) then raise exception 'wrong_schema'; end if; end \$\$;
SQL
 docker exec -i "$CONTAINER_NAME" psql -U postgres -v ON_ERROR_STOP=1 -q <<'SQL'

do $$ declare r record; current_data jsonb; begin
 for r in select * from verification.baseline loop
 execute format('select coalesce(jsonb_agg(to_jsonb(t)-''updated_at''-''customer_id''-''loyalty_entitlement_id''-''display_type''-''color_hex'' order by (to_jsonb(t)-''customer_id''-''loyalty_entitlement_id''-''display_type''-''color_hex'')::text),''[]'') from public.%I t where tenant_id=961',r.table_name) into current_data;
 if current_data is distinct from r.data then raise exception 'preservation_failed_%',r.table_name; end if;
 end loop;
 if exists(select 1 from verification.catalog_contract b left join pg_constraint c on c.conname=b.conname where c.oid is null or pg_get_constraintdef(c.oid)<>b.definition) then raise exception 'historical_constraint_changed'; end if;
 if exists(select 1 from verification.catalog_indexes b left join pg_indexes i on i.indexname=b.indexname where i.indexname is null or i.indexdef<>b.indexdef) then raise exception 'historical_index_changed'; end if;
end $$;

SQL
done
docker exec -i "$CONTAINER_NAME" psql -U postgres -v ON_ERROR_STOP=1 -q <<'SQL'
do $$ begin
 if exists(select 1 from public.site_visit_counters) then raise exception '098_backfill_side_effect'; end if;
 if has_function_privilege('anon','public.record_public_site_visit_safe(integer,text)','execute') or has_function_privilege('authenticated','public.record_public_site_visit_safe(integer,text)','execute') or not has_function_privilege('service_role','public.record_public_site_visit_safe(integer,text)','execute') then raise exception '098_privileges'; end if;
 if has_table_privilege('authenticated','public.site_visit_counters','select') then raise exception '098_table_exposed'; end if;
end $$;
set role service_role;
select public.record_public_site_visit_safe(961,'website');
select public.record_public_site_visit_safe(961,'website');
select public.record_public_site_visit_safe(961,'store');
select public.record_public_site_visit_safe(971,'store');
reset role;
do $$ begin
 if not exists(select 1 from public.site_visit_counters where tenant_id=961 and website_visits=2 and store_visits=1) or not exists(select 1 from public.site_visit_counters where tenant_id=971 and website_visits=0 and store_visits=1) then raise exception '098_counter_scoping'; end if;
 begin perform public.record_public_site_visit_safe(961,'invalid'); raise exception 'invalid_surface_accepted'; exception when sqlstate 'P0001' then if sqlerrm<>'site_visit_surface_invalid' then raise; end if; end;
 begin perform public.record_public_site_visit_safe(999999,'store'); raise exception 'missing_tenant_accepted'; exception when sqlstate 'P0002' then if sqlerrm<>'site_visit_tenant_not_found' then raise; end if; end;
